def HasStrictBoundaries (k : Nat) (boundaries : Fin (k + 1) → Nat) : Prop :=
  StrictMono boundaries ∧ ∀ i : Fin k, boundaries i.castSucc < boundaries (i.castSucc + 1)

def NonemptyIntervalProd (p : Nat) (boundaries : Fin (k : Nat) → Nat) : Prop :=
  ∀ i : Fin k, (∏ n ∈ Finset.Ico (boundaries i.castSucc) (boundaries (i.castSucc + 1)), n) ≡ 1 [MOD p]

